const type = $node["Webhook"].json.body.type;
const body = $node["Webhook"].json.body;
const profile = body.profile || body || $json;
const name = profile.name || "მეგობარო";
const userProfileStr = `სახელი: ${profile.name || ''} ${profile.surname || ''}, დაბადების ადგილი: ${profile.birthPlace || 'საქართველო'}, დაბადების თარიღი: ${profile.day}/${profile.month}/${profile.year}${profile.birthTime ? ', დაბადების დრო: ' + profile.birthTime : ''}.`;

const structureRule = `

სტრუქტურისა და ფორმატირების მკაცრი მოთხოვნა (ბალანსის მოდელის მსგავსად):
1. დაიწყე თბილი პერსონალური მისალმებით: "ძვირფასო ${name},"
2. ტექსტი ააგე მკაფიო თავებად "## [ნომერი]. [თავის სათაური]" ფორმატით.
3. თითოეული თავი გაწერე სუფთა, გამართული აბზაცებით (პარაგრაფებით).
4. ძირითადი თვისებები, მახასიათებლები და პრაქტიკული რეკომენდაციები წარმოადგინე მარკირებული სიის (bullets: - ...) სახით.
5. ბოლო თავი აუცილებლად დაუთმე შემაჯამებელ პრაქტიკულ რჩევებსა და ჰარმონიზაციის გზებს.`;

let prompt = "";
let title = "";

switch (type) {
  case "horoscope":
    title = "დასავლური ჰოროსკოპი (ზოდიაქო)";
    prompt = `დაითვალე და დაადგინე ზოდიაქოს ნიშანი დაბადების თარიღის მიხედვით: ${userProfileStr}.
შემდეგ შეადგინე დასავლური ჰოროსკოპის სრული ანალიზი:
1. ზოდიაქოს ნიშანი, სტიქია და ელემენტი (ცეცხლი, მიწა, ჰაერი, წყალი)
2. ძირითადი ხასიათის თვისებები (დადებითი და უარყოფითი მხარეები)
3. მიმდინარე კოსმოსური ტრენდები და განვითარების გზები შენი დაბადების რუკის მიხედვით.
4. პრაქტიკული რჩევები ყოველდღიური ცხოვრებისთვის.${structureRule}`;
    break;
  case "enneagram":
    title = "ენიაგრამა (Enneagram)";
    prompt = `გამოთვალე და შეადგინე ენიაგრამის შესაძლო ტიპის ანალიზი ამ პიროვნებისთვის: ${userProfileStr}.
დაბადების თარიღისა და დროის ენერგეტიკული მახასიათებლებით განსაზღვრე მისი სავარაუდო დომინანტური ტიპი:
1. ენიაგრამის ტიპი (დასახელება, ნომერი და ძირითადი მოტივაცია)
2. ძირითადი შიში და ძირითადი სურვილი კორონარულ ფსიქოტიპში
3. სტრესისა და განვითარების (ინტეგრაცია/დეზინტეგრაცია) მიმართულებები
4. რეკომენდაციები პიროვნული ზრდისთვის.${structureRule}`;
    break;
  case "psychomatrix":
    title = "ფსიქომატრიცა (პითაგორას კვადრატი)";
    prompt = `ამ მონაცემების მიხედვით: ${userProfileStr}.
წარმოადგინე მათემატიკური და ფსიქოლოგიური ანალიზი პითაგორას ფსიქომატრიცის მიხედვით. დაიანგარიშე პითაგორას სპეციალური რიცხვები და ააგე სრული კვადრატის განმარტება:
1. ხასიათი (1-იანები) და ენერგია (2-იანები)
2. ინტერესი და შემოქმედება (3-იანები), ჯანმრთელობა (4-იანები)
3. ინტუიცია და ლოგიკა (5-იანები), შრომისმოყვარეობა (6-იანები)
4. იღბალი (7-იანები), ვალდებულება/პასუხისმგებლობა (8-იანები), მეხსიერება/ინტელექტი (9-იანები).
5. შემაჯამებელი რეკომენდაციები და პოტენციალის რეალიზება.${structureRule}`;
    break;
  case "numerology":
    title = "ნუმეროლოგია";
    prompt = `დაითვალე დაბადების თარიღის მიხედვით ბედისწერის რიცხვი (Life Path Number) შემდეგი მონაცემების საფუძველზე: ${userProfileStr}.
აღწერე:
1. ბედისწერის რიცხვი და მისი ზოგადი მნიშვნელობა.
2. ცხოვრებისეული მისია და გამოწვევები.
3. ყველაზე შესაფერისი კარიერული მიმართულებები.
4. სასიყვარულო და პარტნიორული ვიბრაციები.
5. პრაქტიკული რჩევები და რეკომენდაციები.${structureRule}`;
    break;
  case "human_design":
    title = "ადამიანის დიზაინი (Human Design)";
    prompt = `დაბადების თარიღის, დროისა და ადგილის მიხედვით გააკეთე ადამიანის დიზაინის (Human Design) შეფასება: ${userProfileStr}.
აღწერე მისი სავარაუდო სტრუქტურა:
1. ენერგეტიკული ტიპი (გენერატორი, პროექტორი, მანიფესტორი, რეფლექტორი, მანიფესტირებადი გენერატორი)
2. პროფილი და მისი მნიშვნელობა
3. სტრატეგია და შინაგანი ავტორიტეტი გადაწყვეტილების მისაღებად
4. ცხოვრებისეული თემა (გზა) და "არასაკუთარი თავის" (Not-Self) თემა.
5. პრაქტიკული რეკომენდაციები ყოველდღიურობაში ენერგიის სწორად სამართავად.${structureRule}`;
    break;
  case "vedic":
    title = "ვედური ასტროლოგია (Jyotish)";
    prompt = `ამ მონაცემების მიხედვით: ${userProfileStr}.
გააკეთე ვედური ასტროლოგიის (ჯიოტიში) სრული განხილვა:
1. მთვარის ნიშანი (რაში) და მისი გავლენა ქვეცნობიერზე
2. სავარაუდო ნაკშატრა (ვარსკვლავური სახლი) და მისი მმართველი პლანეტა
3. კარმული ამოცანები (რაჰუ და კეტუს მდგომარეობა) და სულიერი გაკვეთილები.
4. მიმართულება სულიერი ბედნიერებისთვის (პურუშართა) და პრაქტიკული რჩევები.${structureRule}`;
    break;
  case "bazi":
    title = "ბა-ძი (BaZi)";
    prompt = `მონაცემების საფუძველზე: ${userProfileStr}.
გააკეთე ჩინური ასტროლოგიის BaZi ანალიზი:
1. წლობრივი ცხოველი (დედამიწის ტოტი) და მისი გავლენა გარე სამყაროსთან კონტაქტზე
2. 5 ელემენტის ბალანსი (ხე, ცეცხლი, მიწა, ლითონი, წყალი) - რომელია დომინანტი ან დეფიციტური.
3. დღის მბრძანებელი (Day Master) - პიროვნების ბირთვი.
4. იღბლიანი პერიოდები და რჩევები ენერგეტიკული ბალანსის მხარდასაჭერად.${structureRule}`;
    break;
  case "archetype":
    title = "არქეტიპული ანალიზი (იუნგის მიხედვით)";
    prompt = `დაბადების თარიღის და ფსიქო-ასტროლოგიური მახასიათებლების გათვალისწინებით: ${userProfileStr}.
განსაზღვრე მისი წამყვანი ფსიქოლოგიური არქეტიპები კარლ იუნგის თორმეტი არქეტიპიდან:
1. წამყვანი არქეტიპი და მისი გამოვლინება ხასიათში.
2. ჩრდილოვანი მხარე (Shadow self) და მასთან მუშაობის გზები.
3. შინაგანი მოტივატორი და ღირებულებები.
4. ცხოვრებისეული როლი და განვითარების პოტენციალი.
5. პრაქტიკული რეკომენდაციები და ინტეგრაცია.${structureRule}`;
    break;
}

return { json: { prompt, title, type } };

parameters.jsonBody:
={
  "contents": [
    {
      "parts": [
        {
          "text": "{{ $json.prompt }}"
        }
      ]
    }
  ],
  "systemInstruction": {
    "parts": [
      {
        "text": "შენ ხარ პროფესიონალი ექსპერტი, ასტრო-ფსიქოლოგი და IDC-ის წამყვანი კონსულტანტი. პასუხი გაეცი ქართულ ენაზე, მარკდაუნის (Markdown) ლამაზი ფორმატირებით, ზუსტად ისევე როგორც ბალანსის მოდელის ანალიზში: დაიწყე თბილი მისალმებით (ძვირფასო [სახელი],), ტექსტი ააგე მკაფიო თავებად (## სათაური), სუფთა აბზაცებად და მარკირებულ სიებად (- პუნქტი). პასუხი უნდა იყოს ძალიან სიღრმისეული, პოზიტიური, მხარდამჭერი, ემპათიური და პრაქტიკული რეკომენდაციებით სავსე."
      }
    ]
  }
}
